fs.writeFileSync(path.join(PUB, "_headers"), "/*\n  Cache-Control: public, max-age=0, must-revalidate\n");
console.log("wrote publish/  (Netlify tree; HTML revalidates via _headers, assets keep ?v=BUILD)");
